import{_ as p,a0 as r,w as s,s as i,ao as l,I as a,x as e,a1 as u,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧——怎樣修改你的計算機名字 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧——怎樣修改你的計算機名字 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧——怎樣修改你的計算機名字 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧——怎樣修改你的計算機名字 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Daily Ubuntu Tips – How To Change Your Computer Name","title":"每日Ubuntu小技巧——怎樣修改你的計算機名字","tag":"201311","desc":""},"relativePath":"201311/Daily Ubuntu Tips – How To Change Your Computer Name.md","filePath":"[post].md"}'),d={name:"201311/Daily Ubuntu Tips – How To Change Your Computer Name.md"};function m(T,t,b,g,C,_){const n=r("Link");return s(),i("div",null,[t[11]||(t[11]=l(`<h1 id="每日ubuntu小技巧——怎樣修改你的計算機名字" tabindex="-1">每日Ubuntu小技巧——怎樣修改你的計算機名字 <a class="header-anchor" href="#每日ubuntu小技巧——怎樣修改你的計算機名字" aria-label="Permalink to “每日Ubuntu小技巧——怎樣修改你的計算機名字”">​</a></h1><p>本文又是一篇為Ubuntu新用户和新手準備的文章，將會指導你怎樣在使用Ubuntu時輕鬆更改你的計算機名字，許多用户從來不會考慮在Ubuntu更改計算機名字或者主機名，那是他們最不用考慮擔心的事情。</p><p>許多用户會使用安裝Ubuntu過程中創建或設定的名字，但是對於想要知道怎麼更改名字的新用户，可以繼續接下來的學習。本文不是為Ubuntu專家所準備，是為那些剛剛開始使用Ubuntu的初學者用户。</p><p>那麼，為什麼你又想要更改你的計算機名字？如果除了想要學習怎樣操作，你沒有一個好的理由，那麼就不要學了，反之，如果你有一個好的理由或者想要學習怎樣操作，那麼請繼續。</p><p>按下 <strong>Ctrl - Alt - T</strong> 組合鍵，打開終端。 當終端打開，輸入下列命令，使用gedit編輯hostname文件</p><pre><code>sudo gedit /etc/hostname
</code></pre><p>接下來，無論舊的計算機名字是什麼，換一個新的吧。例如，如果你想要你的計算機名字為“RDOMNU”，先刪除文件內容，輸入 <strong>RDOMNU</strong>，然後保存文件。</p><p>然後，再輸入下列命令來打開hosts文件</p><pre><code>sudo gedit /etc/hosts
</code></pre><p>更改第二行箭頭標記位置的值，使它與你剛才輸入的計算機名字相符，完成後保存文件。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/10/ubuntuhostnamechange.png" alt=""></p><p>就是這樣！重啓你的計算機，然後你的機器將會顯示新的名字。這就是怎麼改變Ubuntu機器的名字。</p><p>試一試吧！</p><hr>`,14)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),u(n,{href:"http://www.liberiangeek.net/2013/10/daily-ubuntu-tips-change-computer-name/"},{default:o(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/10/daily-ubuntu-tips-change-computer-name/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("譯者：",-1)),u(n,{href:"https://blog.csdn.net/Vic___"},{default:o(()=>[...t[2]||(t[2]=[e("Vic___",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),u(n,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),u(n,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const h=p(d,[["render",m]]);export{w as __pageData,h as default};
